37	func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
38		s, err := loadSummarySettings(ctx)
39		if err != nil {
40			return nil, fmt.Errorf("loading settings: %w", err)
41		}
42	
43		if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
44			providerName := types.AgentName(s.SummaryGeneration.Provider)
45			if err := ensureSummaryProviderPresent(ctx, providerName); err != nil {
46				return nil, err
47			}
48			return buildCheckpointSummaryProvider(providerName, s.SummaryGeneration.Model)
49		}
50	
51		candidates := listEnabledSummaryProviders(ctx)
52	
53		switch len(candidates) {
54		case 0:
55			return nil, errors.New("no summary-capable agent CLI is installed on this machine; install one of claude, codex, gemini, cursor, or copilot, or set summary_generation.provider in settings")
56		case 1:
57			return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: single installed provider")
58		default:
59			if !interactive.CanPromptInteractively() {
60				return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: first detected of multiple")
61			}
62	
63			selected, err := promptForSummaryProvider(candidates)
64			if err != nil {
65				return nil, err
66			}
67			provider, err := autoSelectSummaryProvider(ctx, w, selected, "interactive prompt selection")
68			if err != nil {
69				return nil, err
70			}
71			fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
72			return provider, nil
73		}
74	}
