94	func listEnabledSummaryProviders(_ context.Context) []checkpointSummaryProvider {
95		registered := listRegisteredAgents()
96		providers := make([]checkpointSummaryProvider, 0, len(registered))
97		for _, name := range registered {
98			ag, err := getSummaryAgent(name)
99			if err != nil {
100				continue
101			}
102			if _, ok := agent.AsTextGenerator(ag); !ok {
103				continue
104			}
105			// Check CLI binary on PATH, not DetectPresence — a repo can use
106			// Claude Code for development while Codex is the summary provider.
107			if !isSummaryCLIAvailable(name) {
108				continue
109			}
110			providers = append(providers, checkpointSummaryProvider{
111				Name:        name,
112				DisplayName: string(ag.Type()),
113			})
114		}
115		return providers
116	}
